class DB extends ChangeNotifier{SharedPreferences? p;List<Map<String,dynamic>> shops=[];int active=0;bool get ready=>p!=null;Map<String,dynamic> get shop=>shops.isEmpty?<String,dynamic>{}:shops[active];
Future<void> load()async{p=await SharedPreferences.getInstance();try{final x=jsonDecode(p!.getString('rentflow')??'[]');if(x is List)shops=x.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}catch(_){shops=[];}active=p!.getInt('active')??0;if(active<0||active>=shops.length)active=0;notifyListeners();}
Future<void> save()async{await p?.setString('rentflow',jsonEncode(shops));await p?.setInt('active',active);notifyListeners();}
List<Map<String,dynamic>> list(String k)=>((shop[k] is List)?shop[k] as List:const[]).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();
Future<void> addShop(Map<String,dynamic>x)async{shops.add({...x,'items':[],'customers':[],'issues':[],'returns':[]});active=shops.length-1;await save();}
Future<void> updateShop(Map<String,dynamic>x)async{shop.addAll(x);await save();}
Future<void> add(String k,Map<String,dynamic>x)async{if(shop[k] is! List)shop[k]=[];(shop[k] as List).add(x);await save();}
Future<void> edit(String k,int i,Map<String,dynamic>x)async{(shop[k] as List)[i]=x;await save();}
Future<void> stock(String id,int d)async{final a=shop['items'] as List;for(var i=0;i<a.length;i++){final x=Map<String,dynamic>.from(a[i]);if('${x['id']}'==id){x['quantity']=(int.tryParse('${x['quantity']??0}')??0)+d;a[i]=x;break;}}await save();}}
final db=DB();String newId()=>DateTime.now().microsecondsSinceEpoch.toString();String today()=>DateTime.now().toIso8601String().substring(0,10);String money(dynamic x)=>'₹${(double.tryParse('$x')??0).toStringAsFixed(2)}';int rentDays(String a,String b){final x=DateTime.tryParse(a)??DateTime.now(),y=DateTime.tryParse(b)??DateTime.now();final n=y.difference(x).inDays;return n<1?1:n;}

